import { defineConfig } from '@playwright/test'
import { fileURLToPath } from 'node:url'
import base from '../../../playwright.f3-corrections.config'
const root = fileURLToPath(new URL('../../../', import.meta.url))
export default defineConfig({ ...base, testDir: `${root}/tests/e2e`,
  outputDir: fileURLToPath(new URL('./dev-artifacts', import.meta.url)),
  reporter: [['list'], ['json', { outputFile: fileURLToPath(new URL('./dev-results.json', import.meta.url)) }]],
  webServer: { ...base.webServer as object, cwd: root },
})

